import type { Application } from '@nocobase/app-server/application';
import type { AppRouteContribution } from '@nocobase/app-server/router';
import { apiRoutes as todoApiRoutes } from './todos.js';

const routes: readonly AppRouteContribution<Application>[] = [todoApiRoutes];

export default routes;

export interface ScheduleJobOption {
    readonly cron?: string;
    readonly limit?: number;
    /** Interval in milliseconds. */
    readonly every?: number;
    readonly startDate?: Date;
    readonly endDate?: Date;
    /** IANA time zone for `cron`; UTC when omitted. */
    readonly tz?: string;
    /** Fires once on creation, then follows `cron`. Ignored for updates. */
    readonly immediately?: boolean;

export interface ScheduleDefinition {
    readonly key: string;
    readonly title: string;
    readonly description?: string;
    readonly schedule: {
        readonly cron: string;
        readonly timezone?: string;
        readonly from?: Date;
        readonly to?: Date;
        readonly limit?: number;
    };
    readonly target: {
        readonly type: string;
        readonly config: JsonObject;
    };
}
